var a=`1101-mok-pa`;var n=`world-1101`;var t=`LA`;var s=`southeast-asia`;var l=4;var o=51;var r={en:`Mok Pa`,ua:`Мок па`};var d={en:`Mok Pa is a dish from Laos prepared with tilapia, lemongrass, garlic, shallot. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Мок па, страва кухні країни Лаос, яку готують із таких продуктів: тилапія, лемонграс, часник, цибуля шалот. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`tilapia`,650,`g`],[`lemongrass`,35,`g`],[`garlic`,4,`clove`],[`shallot`,120,`g`],[`fish-sauce`,30,`ml`],[`dill`,30,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:13,i:[[`banana-leaf`,8,`leaf`]]},{en:`Steam the already prepared parcels or mixture over gently boiling water for approximately 27 minutes, until fully cooked or set.`,ua:`Готуйте раніше підготовлені згортки або масу на парі над слабким кипінням близько 27 хвилин до готовності.`,t:[`steaming`],m:27,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lime`,2,`pcs`]]}];var m={slug:a,id:n,country:`LA`,region:s,servings:4,minutes:51,title:r,text:d,steps:g};export{t as country,m as default,n as id,o as minutes,s as region,l as servings,a as slug,g as steps,d as text,r as title};